// DataPath UT —— golden DataPath 与重写件 DataPath_xs 双例化，同激励逐拍比全部输出
// ★本文件由 scripts/gen_datapath.py 生成（勿手改，--check 进闸）★
//
// 热身 120 拍：所有写回口 wen=1、地址按顺序扫遍各寄存器堆全部物理寄存器，RegCache 写口全开 ——
//   寄存器堆与 RegCache 的数据阵列都不复位，+vcs+initreg+random / +<n> 档两侧初值不同，
//   先把每一项写成确定值再开始比对。热身最后 40 拍发射口全开、源全走 RegCache：RegCache 读口的
//   地址寄存器只在 ren 时更新（不复位），也要先写一次（+vcs+initreg+<n> 档实测：不这样做，
//   比对开头 3 拍 RegCache 读数两侧不同）。
// 随机阶段：发射 valid 60%、dataSources 在 reg/regcache/forward/bypass/zero/imm/v0 里挑、
//   （发射 valid 每 500 拍在 60/20/3% 三档间换，低档才打得到 TopDown 的"发射少"事件）、
//   redirect 5%（robIdx 随机，约一半的 uop 会被判 isAfter）、ld2Cancel 5%、EXU ready 85%、
//   向量异常借口 10%、写回 wen 50%；约每 5k 拍插一次 2 拍异步复位。
// 覆盖（取重写件核内信号计数）：s0_cancel / 读口仲裁失败 / 写口撞口 / 冲刷 / ld 取消 / og1 失败 /
//   异常借写口 / store-data 多候选选源。
`timescale 1ns/1ps
module tb;
  int unsigned NCYCLES = 200000;
  localparam int WARMUP = 120;
  bit clk = 0, rst = 1;
  int errors = 0, checks = 0, cyc = 0;
  int unsigned issue_pct = 60;   // 发射口 valid 概率：每 500 拍在 60/20/3 三档间换（低档才打得到 TopDown 的"发射少"事件）
  always #5 clk = ~clk;

  function automatic logic [3:0] ds_pick();
    case ($urandom_range(0, 9))
      0, 1, 2, 3: return 4'b1000;   // reg
      4:          return 4'b0110;   // regcache
      5, 6:       return 4'b0001;   // forward
      7:          return 4'b0010;   // bypass
      8:          return 4'b0000;   // zero
      default:    return 4'b0100;   // imm
    endcase
  endfunction

