  // ---- 覆盖（重写件核内信号）----
  int cov_s0cancel = 0, cov_rdblock = 0, cov_wbblock = 0, cov_flushkill = 0, cov_ldkill = 0,
      cov_og1fail = 0, cov_excpw = 0, cov_srcmux = 0;
  int cov_perf [6] = '{0, 0, 0, 0, 0, 0};
  always @(negedge clk) if (cyc > WARMUP + 4) begin
    if (|u_x.u_core.s0_cancel) cov_s0cancel++;
    if (|(u_x.u_core.s0_valid & ~u_x.u_core.src_not_block)) cov_rdblock++;
    if (|(u_x.u_core.s0_valid & ~u_x.u_core.wb_not_block)) cov_wbblock++;
    if (|(u_x.u_core.s0_fire & u_x.u_core.s0_flushed)) cov_flushkill++;
    if (|(u_x.u_core.s0_fire & u_x.u_core.s0_ld_cancel)) cov_ldkill++;
    if (|(u_x.u_core.s1_valid_q & ~u_x.u_core.s1_exuReady)) cov_og1fail++;
    if (|u_x.u_core.excpW_valid) cov_excpw++;
    for (int i = 0; i < 6; i++) if (u_x.u_core.perf_now[i]) cov_perf[i]++;
    if (u_x.u_core.s1_valid_q[25] | u_x.u_core.s1_valid_q[26]) cov_srcmux++;
  end

  initial begin
    if ($value$plusargs("ncycles=%d", NCYCLES)) ;
    rst = 1; repeat (4) @(posedge clk); #2 rst = 0;
    repeat (NCYCLES) begin
      @(posedge clk); cyc++;
      if (cyc % 500 == 0) case ($urandom_range(0, 2)) 0: issue_pct = 60; 1: issue_pct = 20; default: issue_pct = 3; endcase
      if (cyc > WARMUP && $urandom_range(0, 4999) == 0) begin
        #2 rst = 1; @(posedge clk); cyc++; @(posedge clk); cyc++; #2 rst = 0;
      end
    end
    $display("COV s0cancel=%0d rdblock=%0d wbblock=%0d flushkill=%0d ldkill=%0d og1fail=%0d excpw=%0d srcmux=%0d",
             cov_s0cancel, cov_rdblock, cov_wbblock, cov_flushkill, cov_ldkill, cov_og1fail, cov_excpw, cov_srcmux);
    $display("COV perf exec_stall=%0d anyload=%0d store=%0d l1=%0d l2=%0d l3=%0d",
             cov_perf[0], cov_perf[1], cov_perf[2], cov_perf[3], cov_perf[4], cov_perf[5]);
    $display("checks=%0d errors=%0d", checks, errors);
    if (errors == 0 && checks > 1000 && cov_s0cancel > 100 && cov_rdblock > 100 && cov_wbblock > 100
        && cov_flushkill > 100 && cov_ldkill > 100 && cov_og1fail > 100 && cov_excpw > 100 && cov_srcmux > 100
        && cov_perf[0] > 100 && cov_perf[1] > 10 && cov_perf[2] > 10 && cov_perf[3] > 10 && cov_perf[4] > 10 && cov_perf[5] > 10)
      $display("TEST PASSED");
    else
      $display("TEST FAILED");
    $finish;
  end
endmodule
